Here is the corrected function:

```python
def least_interval(tasks, n):
    if not tasks:
        return 0
    tasks = sorted(set(tasks))
    time = 0
    current_tasks = []
    for task in tasks:
        if not current_tasks or task - current_tasks[-1] > n:
            time += 1
            current_tasks.append(task)
        else:
            for i in range(len(current_tasks) - 1, -1, -1):
                if current_tasks[i] == task:
                    current_tasks.pop(i)
                    current_tasks.append(task)
                    break
            time += 1
    return time
```

