def find_words(s, d):
    from collections import Counter
    s_count = Counter(s)
    result = set()

    def dfs(word, s_count):
        if not word:
            result.add("".join(sorted(word)))
            return
        for i, char in enumerate(word):
            if s_count[char] > 0:
                s_count[char] -= 1
                dfs(word[:i] + word[i+1:], s_count)
                s_count[char] += 1

    for word in d:
        dfs(word, s_count.copy())

    return [word for word in d if ''.join(sorted(word)) in result]

